$names = 'jump_pins_60fps','test_jump_states_60fps','test_raccoon_rig_60fps','test_jump_edges_30fps','test_jump_edges_60fps','test_jump_edges_144fps','a3_asset_check_60fps','normal_map_calibration_60fps','test_materials_60fps','test_leaf_burst_config_60fps','test_campfire_smoke_config_60fps','cost_effects_60fps','sound-test_60fps','bubble-test_60fps','camp-test_60fps','tasks-test_60fps','plan-test_60fps','tutorial-test_60fps','cones-test_30fps','cones-test_60fps','cones-test_144fps','cone-shader-test_30fps','cone-shader-test_60fps','cone-shader-test_144fps','fire-test_60fps','tent-test_60fps','bearbag-test_60fps','leaf-burst-test_60fps','smoke-test_60fps','smoke-load-test_60fps','waves-test_realtime','title-test_realtime'
foreach ($n in $names) {
  $f = "logs\$n.log"
  $sum = Select-String -Path $f -Pattern 'RESULT|^Done|check\(s\) failed|passed \(' | Select-Object -Last 1
  $fails = (Select-String -Path $f -Pattern '^\s*(FAIL|fail)\b' -CaseSensitive).Count
  $t = (Get-Item $f).LastWriteTime.ToString('HH:mm')
  $line = '(no summary line)'
  if ($sum) { $line = $sum.Line.Trim() }
  "{0,-34} {1}  fails={2}  {3}" -f $n, $t, $fails, $line
}

